    { id: "en-cgl-2", text: "The famous prehistoric bronze 'Dancing Girl' was excavated from which Indus Valley site?", options: ["Mohenjo-daro", "Harappa", "Lothal", "Kalibangan"], answer: "Mohenjo-daro", explanation: "Discovered in 1926 by Ernest Mackay, this artifact highlights advanced lost-wax bronze casting." },
    { id: "en-cgl-3", text: "Which Five Year Plan of India was based on the Mahalanobis heavy industrialization model?", options: ["Second Plan (1956-61)", "First Plan (1951-56)", "Third Plan (1961-66)", "Fourth Plan (1969-74)"], answer: "Second Plan (1956-61)", explanation: "Formulated by PC Mahalanobis, it prioritized steel plants and capital goods industries." }
